def d3_rule(g):
 R,C=len(g),len(g[0]); o=[row[:] for row in g]
 # identify first all-one horizontal separator row
 sep=next((r for r,row in enumerate(g) if all(v==1 for v in row)),None)
 # selected domain rows below separator (if any), otherwise infer bottom-side with top-touching component excluded
 if sep is not None:
  # paint all 8-neighbor cells below/on the divider (rows > sep) and all neighbors of 1s below it, but only dr>=0 from internal shapes
  for c in range(C):
   if g[sep][c]==1 and sep+1<R and g[sep+1][c]==8:o[sep+1][c]=7
  # actual 1 obstacles below divider: 7 down/sides; bottom-edge obstacles permit upwards
  for r in range(sep+1,R):
   for c in range(C):
    if g[r][c]!=1:continue
    for dr in (-1,0,1):
     if dr<0:continue
     for dc in (-1,0,1):
      if dr==dc==0:continue
      nr,nc=r+dr,c+dc
      if 0<=nr<R and 0<=nc<C and g[nr][nc]==8:o[nr][nc]=7
  # grid frame below separator plus 1-touch side borders
  for r in range(sep+1,R):
   if g[r][0]==8:o[r][0]=7
   if g[r][C-1]==8:o[r][C-1]=7
  for c in range(C):
   if g[R-1][c]==8:o[R-1][c]=7
 return o
